<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { api, event, type User, type State, type Row } from '../services/api';
import { queue } from '../services/offline';
const user=ref<User|null>(null), state=ref<State|null>(null), tab=ref('resumen');
const busy=ref(false), message=ref(''), error=ref(''), online=ref(navigator.onLine), pending=ref(0), detail=ref<Row|null>(null);
const loginForm=ref({username:'ignacio',password:''});
const search=ref(''), clientId=ref(0), editingClient=ref(0), editingAddress=ref(0), editingVehicle=ref(0);
const clientForm=ref({nombre:'',telefono:'',rut:'',email:''});
const addressForm=ref({id_cliente:0,etiqueta:'Domicilio',calle:'',numero:'',comuna:'',ciudad:'Santiago',latitud:null as number|null,longitud:null as number|null});
const orderForm=ref({id_cliente:0,id_direccion:0,cantidad:2,tipo_producto:'Bidón de agua purificada 20L'});
const paymentForm=ref({id_pedido:0,medio:'TRANSFERENCIA',monto:0,comprobante:''});
const vehicleForm=ref({patente:'',modelo:'',capacidad:20});
const turnForm=ref({fecha:new Date().toLocaleDateString('en-CA'),nombre:'Mañana',chofer:'chofer',vehiculo_id:null as number|null});
const delivery=ref<Row|null>(null), deliveryForm=ref({entregados:0,vacios:0,rotos:0,ausente:false,aceptacion_parcial:false,detalle:''});
const inventoryForm=ref({cantidad:1,origen:'ROTOS',motivo:'',revisado:false,eliminado:false});
const modules=computed(()=>user.value?.rol==='chofer'?[['ruta','Mi reparto']]:[['resumen','Resumen'],['clientes','Clientes'],['pedidos','Pedidos'],['pagos','Pagos'],['despacho','Despacho'],['inventario','Inventario']]);
const money=(n:unknown)=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP'}).format(Number(n??0));
const date=(s:unknown)=>s?new Date(String(s)).toLocaleString('es-CL',{timeZone:'America/Santiago'}):'—';
const clients=computed(()=>state.value?.clientes.filter(c=>`${c.nombre} ${c.telefono} ${c.rut??''}`.toLowerCase().includes(search.value.toLowerCase()))??[]);
const addresses=computed(()=>state.value?.direcciones.filter(d=>d.id_cliente===clientId.value)??[]);
const orderAddresses=computed(()=>state.value?.direcciones.filter(d=>d.id_cliente===orderForm.value.id_cliente)??[]);
const orders=computed(()=>state.value?.pedidos.filter(p=>`${p.id_pedido} ${p.nombre} ${p.calle}`.toLowerCase().includes(search.value.toLowerCase()))??[]);
const stock=(category:string)=>Number(state.value?.inventario.find(i=>i.categoria===category)?.cantidad??0);
const physicalTotal=computed(()=>state.value?.inventario.reduce((n,i)=>n+Number(i.cantidad),0)??0);
const load=computed(()=>state.value?.paradas.reduce((n,p)=>n+p.cantidad,0)??0);
const availableVehicles=computed(()=>state.value?.vehiculos.filter(v=>v.activo)??[]);
const notice=computed(()=>{
  if(user.value?.rol!=='administrativo')return '';
  const id=orderForm.value.id_cliente;const c=state.value?.clientes.find(c=>c.id_cliente===id);
  return c?.nota_no_retornados||(state.value?.retornos.some(r=>r.cliente_id===id&&r.estado==='no_retornaron')?'Tiene botellones no retornados. Coordina por WhatsApp y autoriza este pedido.':'');
});
async function refresh(){state.value=await api<State>('/state');if(user.value?.rol==='chofer')localStorage.setItem('pi_driver_snapshot',JSON.stringify(state.value));}
async function run(fn:()=>Promise<unknown>,success='Cambios guardados'){
  if(busy.value)return;busy.value=true;error.value='';message.value='';
  try{await fn();if(user.value)await refresh();message.value=success;}catch(e){error.value=e instanceof Error?e.message:'No se pudo completar la operación';}
  finally{busy.value=false;}
}
async function login(){await run(async()=>{user.value=await api<User>('/auth/login','POST',loginForm.value);loginForm.value.password='';tab.value=user.value.rol==='chofer'?'ruta':'resumen';},'Sesión iniciada');}
async function logout(){await run(async()=>{await api('/auth/logout','POST',{});await queue.clear();localStorage.removeItem('pi_driver_snapshot');user.value=null;state.value=null;},'Sesión cerrada');}
function selectClient(c:Row){clientId.value=c.id_cliente;editingClient.value=c.id_cliente;clientForm.value={nombre:c.nombre,telefono:c.telefono??'',rut:c.rut??'',email:c.email??''};addressForm.value.id_cliente=c.id_cliente;}
function newClient(){editingClient.value=0;clientForm.value={nombre:'',telefono:'',rut:'',email:''};}
async function saveClient(){await run(async()=>{const c=await api('/clients'+(editingClient.value?'/'+editingClient.value:''),editingClient.value?'PATCH':'POST',clientForm.value);clientId.value=c.id_cliente;addressForm.value.id_cliente=c.id_cliente;editingClient.value=c.id_cliente;});}
function editAddress(d:Row){editingAddress.value=d.id_direccion;addressForm.value={id_cliente:d.id_cliente,etiqueta:d.etiqueta,calle:d.calle,numero:d.numero??'',comuna:d.comuna??'',ciudad:d.ciudad??'Santiago',latitud:d.latitud,longitud:d.longitud};}
async function saveAddress(){await run(async()=>{await api('/addresses'+(editingAddress.value?'/'+editingAddress.value:''),editingAddress.value?'PATCH':'POST',addressForm.value);editingAddress.value=0;addressForm.value={id_cliente:clientId.value,etiqueta:'Domicilio',calle:'',numero:'',comuna:'',ciudad:'Santiago',latitud:null,longitud:null};});}
function prefill(){const last=state.value?.pedidos.find(p=>p.id_cliente===orderForm.value.id_cliente);orderForm.value.id_direccion=last?.id_direccion_entrega??orderAddresses.value[0]?.id_direccion??0;orderForm.value.cantidad=last?.cantidad??2;orderForm.value.tipo_producto=last?.tipo_producto??'Bidón de agua purificada 20L';}
function choosePayment(){const p=state.value?.pedidos.find(p=>p.id_pedido===paymentForm.value.id_pedido);paymentForm.value.monto=p?Math.max(0,Number(p.cantidad*p.precio_unitario)-Number(p.pagado)):0;}
async function savePayment(){await run(()=>api('/payments','POST',{...paymentForm.value,evento:event()}),'Pago registrado para revisión');}
async function validatePayment(p:Row,status:string){let reason='';if(status==='RECHAZADO'){reason=prompt('Motivo del rechazo')??'';if(!reason)return;}await run(()=>api(`/payments/${p.id_pago}/validate`,'POST',{estado:status,motivo:reason}),'Pago revisado; despacho actualizado si corresponde');}
async function authorize(p:Row,decision:string){const reason=prompt('Describe la coordinación por WhatsApp o la autorización sin retorno');if(!reason)return;await run(()=>api(`/orders/${p.id_pedido}/authorize`,'POST',{decision,motivo:reason}));}
function editVehicle(v:Row){editingVehicle.value=v.id;vehicleForm.value={patente:v.patente,modelo:v.modelo,capacidad:v.capacidad};}
async function saveVehicle(){await run(async()=>{await api('/vehicles'+(editingVehicle.value?'/'+editingVehicle.value:''),editingVehicle.value?'PATCH':'POST',vehicleForm.value);editingVehicle.value=0;vehicleForm.value={patente:'',modelo:'',capacidad:20};});}
async function deleteVehicle(v:Row){await run(()=>api('/vehicles/'+v.id,'DELETE',{}),'Vehículo desactivado; historial conservado');}
async function assignVehicle(e:Event){const id=(e.target as HTMLSelectElement).value;await run(()=>api(`/turns/${state.value?.turno?.id}/vehicle`,'POST',{vehiculo_id:id?Number(id):null}));}
function openDelivery(p:Row){delivery.value=p;deliveryForm.value={entregados:p.cantidad,vacios:p.cantidad,rotos:0,ausente:false,aceptacion_parcial:false,detalle:''};}
async function saveDelivery(){if(!delivery.value)return;const path=`/stops/${delivery.value.id}/deliver`;const body={...deliveryForm.value,evento:event()};
 if(!online.value){await queue.add({id:body.evento,username:user.value!.username,path,body});pending.value=(await queue.all()).length;delivery.value=null;message.value='Registro pendiente de sincronización. No se ha confirmado en el servidor.';return;}
 await run(async()=>{await api(path,'POST',body);delivery.value=null;},'Entrega e incidencias registradas');
}
async function collect(r:Row){const path=`/returns/${r.id}/collect`;if(!online.value){await queue.add({id:event(),username:user.value!.username,path,body:{}});pending.value=(await queue.all()).length;message.value='Retiro guardado para sincronizar. La alerta se resolverá al confirmarse en el servidor.';return;}await run(()=>api(path,'POST',{}),'Retiro confirmado; alerta resuelta');}
async function writeoffReturn(r:Row){const evidence=prompt('Evidencia de revisión del administrador para este caso no recuperado');if(!evidence)return;await run(()=>api(`/returns/${r.id}/writeoff`,'POST',{evidencia:evidence}));}
async function stockOperation(action:string){await run(()=>api(`/inventory/0/${action}`,'POST',{...inventoryForm.value,evento:event()}));}
async function sync(){online.value=navigator.onLine;if(!online.value||!user.value)return;
 for(const item of await queue.all()){if(item.username!==user.value.username)continue;try{await api(item.path,'POST',item.body);await queue.remove(item.id);}catch(e){error.value='Registro pendiente: '+(e instanceof Error?e.message:'Revisa la incidencia');break;}}
 pending.value=(await queue.all()).length;await refresh();
}
function network(){online.value=navigator.onLine;if(online.value)void sync();}
onMounted(async()=>{window.addEventListener('online',network);window.addEventListener('offline',network);try{user.value=await api<User>('/auth/me');tab.value=user.value.rol==='chofer'?'ruta':'resumen';await refresh();pending.value=(await queue.all()).length;}catch{if(!navigator.onLine){try{const cached=JSON.parse(localStorage.getItem('pi_driver_snapshot')??'null') as State|null;if(cached?.user.rol==='chofer'){state.value=cached;user.value=cached.user;tab.value='ruta';pending.value=(await queue.all()).length;return;}}catch{/* Sin una ruta local válida se requiere iniciar sesión. */}}user.value=null;}});
onUnmounted(()=>{window.removeEventListener('online',network);window.removeEventListener('offline',network);});
</script>

<template>
  <main v-if="!user" class="login-page">
    <div class="login-intro"><span class="eyebrow">Proyecto integrado / Sprint 1</span><h1>Una operación.<br>Todo conectado.</h1><p>Clientes, pedidos y reparto de agua purificada.</p><div class="login-rule"></div><p class="small">Versión local · Datos de prueba</p></div>
    <form class="login-card card" @submit.prevent="login"><span class="eyebrow">Bienvenido</span><h2>Iniciar sesión</h2><p>Usa la cuenta del perfil que necesitas probar.</p><label>Usuario<input v-model="loginForm.username" required autocomplete="username" /></label><label>Contraseña<input v-model="loginForm.password" required type="password" autocomplete="current-password" /></label><button class="btn btn-primary" :disabled="busy">{{ busy?'Ingresando…':'Entrar' }}</button><p class="small">Credenciales de prueba en <code>.local/credenciales.txt</code> dentro de la carpeta del proyecto.</p><p v-if="error" role="alert" class="error">{{ error }}</p></form>
  </main>
  <div v-else class="platform">
    <aside class="sidebar"><a href="/" class="brand"><span class="drop">●</span><span>Aguas<br><b>purificadas</b></span></a><span class="eyebrow nav-label">Operación</span><nav><button v-for="[key,label] in modules" :key="key" :class="{selected:tab===key}" @click="tab=key;search=''">{{ label }}<span>↗</span></button></nav><div class="sidebar-footer"><span class="small">Instancia local</span><b>{{ user.nombre }}</b><span>{{ user.rol }}</span><button class="btn btn-secondary" @click="logout">Cerrar sesión</button></div></aside>
    <div class="workspace"><header class="topbar"><span>Gestión y distribución / {{ modules.find(m=>m[0]===tab)?.[1] }}</span><span class="status-dot">{{ online?'Conectado':'Sin conexión' }}</span></header><div class="content"><p v-if="message" class="success" role="status">{{ message }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="pending" class="warning">{{ pending }} registro(s) pendientes de sincronización. <button @click="sync">Sincronizar</button></p>
      <template v-if="state">
      <section v-if="tab==='resumen'"><div class="section-heading"><div><span class="eyebrow">Visibilidad operativa</span><h1>El día, en una mirada.</h1><p>Disponibilidad, incidencias y pedidos que necesitan atención.</p></div><button class="btn btn-secondary" @click="run(refresh,'Datos actualizados')">Actualizar</button></div><div class="metrics"><article class="metric"><span>Disponibles llenos</span><strong>{{ stock('LLENO') }}</strong><small>Listos para cargar</small></article><article class="metric"><span>Total físico</span><strong>{{ physicalTotal }}</strong><small>Incluye vacíos, tránsito y rotos</small></article><article class="metric"><span>Retiros pendientes</span><strong>{{ state.retornos.length }}</strong><small>Incidencias con fecha original</small></article><article class="metric"><span>Saldo por entregar</span><strong>{{ state.pedidos.reduce((n,p)=>n+p.cantidad-p.entregados,0) }}</strong><small>Unidades pendientes</small></article></div><div class="card panel"><h2>Alertas de devolución</h2><p v-if="!state.retornos.length" class="empty">No hay retiros pendientes.</p><div v-for="r in state.retornos" :key="r.id" class="list-row"><div><b>{{ r.nombre }}</b><p>{{ r.cantidad }} botellón(es) · {{ date(r.fecha) }}</p></div><span class="badge badge-warning">{{ r.dias }} días · {{ r.estado }}</span><button v-if="user.rol==='administrador'&&r.dias>=60" class="btn btn-secondary" @click="writeoffReturn(r)">Revisar baja</button></div></div><div class="card panel"><h2>Últimos movimientos de la operación</h2><div v-for="a in state.auditoria.slice(0,6)" :key="a.id" class="list-row"><b>{{ a.accion }}</b><span>{{ a.actor }} · {{ date(a.fecha) }}</span></div><p v-if="!state.auditoria.length" class="empty">Las acciones que registres aparecerán aquí.</p></div></section>
      <section v-if="tab==='clientes'"><div class="section-heading"><div><span class="eyebrow">Directorio</span><h1>Clientes y direcciones</h1><p>Una ficha por cliente, varias direcciones de entrega.</p></div><button class="btn btn-primary" @click="newClient">Nuevo cliente</button></div><input v-model="search" class="search" placeholder="Buscar nombre, teléfono o RUT" aria-label="Buscar clientes" /><div class="two-columns"><div class="card panel"><div v-for="c in clients" :key="c.id_cliente" class="client-row" :class="{active:clientId===c.id_cliente}" @click="selectClient(c)"><b>{{ c.nombre }}</b><span>{{ c.telefono }} · {{ c.rut??'Sin RUT' }}</span><p v-if="user.rol==='administrativo'&&c.nota_no_retornados" class="warning">{{ c.nota_no_retornados }}</p></div></div><div><form class="card panel form-grid" @submit.prevent="saveClient"><h2>{{ editingClient?'Editar ficha':'Crear cliente' }}</h2><label>Nombre<input v-model="clientForm.nombre" required maxlength="100" /></label><label>Teléfono<input v-model="clientForm.telefono" required placeholder="+56912345678" /></label><label>RUT<input v-model="clientForm.rut" maxlength="12" /></label><label>Email<input v-model="clientForm.email" type="email" /></label><button class="btn btn-primary" :disabled="busy">Guardar ficha</button></form><div v-if="clientId" class="card panel"><h2>Direcciones de la ficha</h2><div v-for="d in addresses" :key="d.id_direccion" class="list-row"><div><b>{{ d.etiqueta }}</b><p>{{ d.calle }} {{ d.numero }}, {{ d.comuna }}</p></div><button class="btn btn-secondary" @click="editAddress(d)">Editar</button></div><form class="form-grid" @submit.prevent="saveAddress"><h3>{{ editingAddress?'Editar dirección':'Agregar dirección' }}</h3><label>Etiqueta<input v-model="addressForm.etiqueta" required /></label><label>Calle<input v-model="addressForm.calle" required /></label><label>Número<input v-model="addressForm.numero" /></label><label>Comuna<input v-model="addressForm.comuna" required /></label><label>Ciudad<input v-model="addressForm.ciudad" required /></label><div class="two-columns"><label>Latitud<input v-model.number="addressForm.latitud" type="number" step="any" min="-90" max="90" /></label><label>Longitud<input v-model.number="addressForm.longitud" type="number" step="any" min="-180" max="180" /></label></div><button class="btn btn-primary" :disabled="busy">Guardar dirección</button></form></div></div></div></section>
      <section v-if="tab==='pedidos'"><div class="section-heading"><div><span class="eyebrow">Recepción por WhatsApp</span><h1>Pedidos y ventas</h1><p>El historial prellena el siguiente pedido. Pago anticipado y autorización antes del reparto.</p></div></div><form class="card panel horizontal-form" @submit.prevent="run(()=>api('/orders','POST',orderForm),'Pedido registrado')"><label>Cliente<select v-model.number="orderForm.id_cliente" required @change="prefill"><option :value="0" disabled>Selecciona un cliente</option><option v-for="c in state.clientes" :key="c.id_cliente" :value="c.id_cliente">{{ c.nombre }}</option></select></label><label>Dirección<select v-model.number="orderForm.id_direccion" required><option :value="0" disabled>Selecciona dirección</option><option v-for="d in orderAddresses" :key="d.id_direccion" :value="d.id_direccion">{{ d.calle }} {{ d.numero }}</option></select></label><label>Cantidad<input v-model.number="orderForm.cantidad" type="number" min="1" max="1000" required /></label><label>Tipo<input v-model="orderForm.tipo_producto" required /></label><button class="btn btn-primary" :disabled="busy">Crear pedido</button><p v-if="notice" class="warning full">{{ notice }}</p></form><input v-model="search" class="search" placeholder="Buscar pedido, nombre o dirección" aria-label="Buscar pedidos" /><div class="table-wrap card"><table><thead><tr><th>Pedido</th><th>Cliente / dirección</th><th>Unidades</th><th>Pago</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="p in orders" :key="p.id_pedido"><td><button class="btn btn-secondary" @click="run(async()=>{detail=await api(`/orders/${p.id_pedido}`)},'Detalle del pedido')">#{{ p.id_pedido }} ↗</button></td><td><b>{{ p.nombre }}</b><small>{{ p.calle }} {{ p.numero }}, {{ p.comuna }}</small></td><td>{{ p.entregados }} / {{ p.cantidad }}<small>{{ p.tipo_producto }}</small></td><td>{{ money(p.pagado) }}<small>de {{ money(p.cantidad*p.precio_unitario) }}</small></td><td><span class="badge badge-neutral">{{ p.nombre_estado }}</span><small>{{ p.autorizacion }}</small></td><td><div class="actions"><template v-if="p.autorizacion==='PENDIENTE'&&user.rol==='administrativo'"><button class="btn btn-secondary" @click="authorize(p,'CON_RETORNO')">Autorizar con retorno</button><button class="btn btn-secondary" @click="authorize(p,'SIN_RETORNO')">Autorizar sin retorno</button></template><button v-if="p.entregados<p.cantidad&&Number(p.pagado)>=p.cantidad*p.precio_unitario" class="btn btn-secondary" @click="run(()=>api(`/orders/${p.id_pedido}/enqueue`,'POST',{}))">Incluir en turno</button></div></td></tr></tbody></table></div></section>
      <section v-if="tab==='pagos'"><div class="section-heading"><div><span class="eyebrow">Conciliación</span><h1>Pagos anticipados</h1><p>Registrar, confirmar o rechazar con responsable y fecha.</p></div><span class="badge badge-warning">Webpay: simulación local</span></div><form class="card panel horizontal-form" @submit.prevent="savePayment"><label>Pedido<select v-model.number="paymentForm.id_pedido" required @change="choosePayment"><option :value="0" disabled>Selecciona pedido</option><option v-for="p in state.pedidos.filter(p=>p.entregados<p.cantidad)" :key="p.id_pedido" :value="p.id_pedido">#{{ p.id_pedido }} · {{ p.nombre }}</option></select></label><label>Medio<select v-model="paymentForm.medio"><option>TRANSFERENCIA</option><option>WEBPAY</option></select></label><label>Monto<input v-model.number="paymentForm.monto" type="number" min="1" required /></label><label v-if="paymentForm.medio==='TRANSFERENCIA'">Referencia del comprobante<input v-model="paymentForm.comprobante" required /></label><button class="btn btn-primary" :disabled="busy">Registrar pago</button></form><div class="table-wrap card"><table><thead><tr><th>Pedido</th><th>Medio</th><th>Monto</th><th>Comprobante</th><th>Revisión</th><th>Acción</th></tr></thead><tbody><tr v-for="p in state.pagos" :key="p.id_pago"><td><button class="btn btn-secondary" @click="run(async()=>{detail=await api(`/orders/${p.id_pedido}`)},'Detalle del pedido')">#{{ p.id_pedido }} ↗</button></td><td>{{ p.medio }}</td><td>{{ money(p.monto) }}</td><td>{{ p.comprobante }}</td><td><span class="badge badge-neutral">{{ p.estado }}</span><small>{{ p.validado_por??'Por revisar' }} · {{ date(p.fecha_validacion) }}</small><small>{{ p.motivo_rechazo }}</small></td><td><div v-if="p.estado==='PENDIENTE'" class="actions"><button class="btn btn-primary" @click="validatePayment(p,'CONFIRMADO')">Confirmar</button><button class="btn btn-secondary" @click="validatePayment(p,'RECHAZADO')">Rechazar</button></div></td></tr></tbody></table></div><div class="card panel"><h2>Cuentas de prueba</h2><div v-for="c in state.cuentas" :key="c.id" class="list-row"><b>{{ c.nombre }} · {{ c.numero }}</b><span>{{ c.comprobantes }} comprobantes · {{ c.activa?'Activa':'En espera' }}</span></div><p class="small">La cuenta activa rota al procesar 45 comprobantes confirmados.</p></div></section>
      <section v-if="tab==='despacho'"><div class="section-heading"><div><span class="eyebrow">Preparación</span><h1>Despacho y vehículos</h1><p>Planifica el turno y valida la capacidad antes de cargar.</p></div></div><div class="two-columns"><div class="card panel"><h2>Vehículos</h2><div v-for="v in availableVehicles" :key="v.id" class="list-row"><div><b>{{ v.patente }}</b><p>{{ v.modelo }} · {{ v.capacidad }} botellones</p></div><div class="actions"><button class="btn btn-secondary" @click="editVehicle(v)">Editar</button><button class="btn btn-secondary" @click="deleteVehicle(v)">Eliminar</button></div></div><form class="form-grid" @submit.prevent="saveVehicle"><h3>{{ editingVehicle?'Editar vehículo':'Agregar vehículo' }}</h3><label>Patente<input v-model="vehicleForm.patente" required /></label><label>Modelo<input v-model="vehicleForm.modelo" required /></label><label>Capacidad<input v-model.number="vehicleForm.capacidad" type="number" min="1" required /></label><button class="btn btn-primary" :disabled="busy">Guardar vehículo</button></form></div><div class="card panel"><template v-if="state.turno"><h2>Turno {{ state.turno.nombre }}</h2><p>{{ String(state.turno.fecha).slice(0,10) }} · {{ state.turno.estado }}</p><div class="metric compact"><span>Carga planificada</span><strong>{{ load }}</strong><small>Botellones para este turno</small></div><label>Vehículo del turno<select :value="state.turno.vehiculo_id??''" :disabled="state.turno.estado!=='preparacion'" @change="assignVehicle"><option value="">Sin asignar</option><option v-for="v in availableVehicles" :key="v.id" :value="v.id">{{ v.patente }} · {{ v.capacidad }} unidades</option></select></label><div class="actions spaced"><button v-if="state.turno.estado==='preparacion'" class="btn btn-primary" @click="run(()=>api(`/turns/${state!.turno!.id}/start`,'POST',{}),'Carga registrada y turno en ruta')">Cargar y salir</button><button v-if="state.turno.estado==='en_ruta'" class="btn btn-primary" @click="run(()=>api(`/turns/${state!.turno!.id}/close`,'POST',{}),'Turno cerrado y vehículo descargado')">Cerrar turno y cuadrar</button></div><div v-for="p in state.paradas" :key="p.id" class="list-row"><b>{{ p.nombre }}</b><span>{{ p.cantidad }} unidades · retiro {{ p.retiro_pendiente }} · {{ p.estado }}</span></div></template><form v-else class="form-grid" @submit.prevent="run(()=>api('/turns','POST',turnForm))"><h2>Nuevo turno</h2><label>Fecha<input v-model="turnForm.fecha" type="date" required /></label><label>Nombre<input v-model="turnForm.nombre" required /></label><label>Chofer<input v-model="turnForm.chofer" required /></label><label>Vehículo<select v-model="turnForm.vehiculo_id"><option :value="null">Sin asignar</option><option v-for="v in availableVehicles" :key="v.id" :value="v.id">{{ v.patente }}</option></select></label><button class="btn btn-primary">Crear turno</button></form></div></div></section>
      <section v-if="tab==='ruta'"><div class="section-heading"><div><span class="eyebrow">Hoja de ruta</span><h1>Mi reparto</h1><p>Paradas en orden geográfico. Registra cantidades reales.</p></div></div><div class="route-grid"><article v-for="(p,index) in state.paradas" :key="p.id" class="card panel stop"><span class="eyebrow">Parada {{ index+1 }} / {{ p.estado }}</span><h2>{{ p.nombre }}</h2><p>{{ p.calle }} {{ p.numero }}, {{ p.comuna }}</p><div class="stop-quantity">{{ p.cantidad }} <span>botellón(es)</span></div><a class="btn btn-secondary" :href="`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.calle+' '+p.numero+', '+p.comuna)}`" target="_blank" rel="noopener">Ver dirección</a><div v-for="r in state.retornos.filter(r=>r.cliente_id===p.id_cliente)" :key="r.id" class="warning"><b>Retirar {{ r.cantidad }} vacío(s)</b><p>Desde {{ date(r.fecha) }}</p><button v-if="state.turno?.estado==='en_ruta'" class="btn btn-secondary" @click="collect(r)">Marcar retirado</button></div><button v-if="p.estado==='en_ruta'" class="btn btn-primary" @click="openDelivery(p)">Registrar entrega o novedad</button></article><p v-if="!state.paradas.length" class="empty">No tienes paradas asignadas.</p></div></section>
      <section v-if="tab==='inventario'"><div class="section-heading"><div><span class="eyebrow">Libro de movimientos</span><h1>Bodegas e inventario</h1><p>Los saldos se reconstruyen desde el modelo de Agustín.</p></div><span class="badge badge-neutral">Total físico: {{ physicalTotal }}</span></div><div class="metrics"><article v-for="i in state.inventario" :key="i.categoria" class="metric"><span>{{ i.categoria }}</span><strong>{{ i.cantidad }}</strong></article></div><div class="card panel"><h2>Roturas informadas por el chofer</h2><div v-for="r in state.reportes.filter(r=>!r.clasificado)" :key="r.id" class="list-row"><div><b>Pedido #{{ r.pedido_id }} · {{ r.cantidad }} roto(s)</b><p>{{ r.detalle }}</p></div><button class="btn btn-secondary" @click="run(()=>api(`/inventory/${r.id}/classify`,'POST',{}),'Roto clasificado; permanece en total físico')">Mover a bodega de rotos</button></div><p v-if="!state.reportes.some(r=>!r.clasificado)" class="empty">Sin reportes por clasificar.</p></div><form v-if="user.rol==='administrador'" class="card panel form-grid" @submit.prevent="stockOperation('writeoff')"><h2>Operaciones del administrador</h2><div class="horizontal-form"><label>Cantidad<input v-model.number="inventoryForm.cantidad" type="number" min="1" required /></label><label>Origen de rotos<select v-model="inventoryForm.origen"><option>ROTOS</option><option>BODEGA</option></select></label><label>Motivo<input v-model="inventoryForm.motivo" required /></label></div><label class="check"><input v-model="inventoryForm.revisado" type="checkbox" /> Revisé físicamente y confirmé que está inservible</label><label class="check"><input v-model="inventoryForm.eliminado" type="checkbox" /> Eliminé físicamente los envases indicados</label><div class="actions"><button class="btn btn-primary" :disabled="busy">Dar de baja rotos</button><button type="button" class="btn btn-secondary" @click="stockOperation('fill')">Embotellar vacíos</button><button type="button" class="btn btn-secondary" @click="stockOperation('initial')">Registrar ingreso</button></div></form><div class="card panel"><h2>Control de cuadratura</h2><p v-if="!state.inconsistencias.length" class="success">Sin inconsistencias en el libro de movimientos.</p><p v-for="i in state.inconsistencias" :key="i.detalle" class="error">{{ i.problema }}: {{ i.detalle }}</p></div></section>
      </template>
    </div><footer class="page-footer">Proyecto integrado · Entorno de prueba local · No se cobra garantía</footer></div>
    <div v-if="detail" class="modal-overlay" @click.self="detail=null"><div class="modal-content panel form-grid"><div class="section-heading"><h2>Pedido #{{ detail.id_pedido }}</h2><button class="btn btn-secondary" @click="detail=null">Cerrar</button></div><p>{{ detail.nombre }} · {{ detail.calle }} {{ detail.numero }}</p><p>{{ detail.entregados }} de {{ detail.cantidad }} entregados · {{ money(detail.pagado) }} pagados</p><h3>Historial de estados</h3><div v-for="h in detail.historial" :key="h.id_historial" class="list-row"><div><b>{{ h.nombre_estado }}</b><p>{{ h.observacion }}</p></div><small>{{ h.responsable }} · {{ date(h.fecha_cambio) }}</small></div></div></div>
    <div v-if="delivery" class="modal-overlay" @click.self="delivery=null"><form class="modal-content panel form-grid" @submit.prevent="saveDelivery"><div class="section-heading"><h2>Entrega a {{ delivery.nombre }}</h2><button type="button" class="btn btn-secondary" @click="delivery=null">Cerrar</button></div><label class="check"><input v-model="deliveryForm.ausente" type="checkbox" /> Cliente ausente: coordinar regreso hoy o mañana</label><template v-if="!deliveryForm.ausente"><label>Entregados<input v-model.number="deliveryForm.entregados" type="number" min="0" :max="delivery.cantidad" required /></label><label>Vacíos del pedido retirados<input v-model.number="deliveryForm.vacios" type="number" min="0" :max="deliveryForm.entregados" required /></label><label>Rotos durante el trayecto<input v-model.number="deliveryForm.rotos" type="number" min="0" :max="delivery.cantidad" /></label><label>Detalle de incidencia<textarea v-model="deliveryForm.detalle"></textarea></label><label v-if="deliveryForm.entregados<delivery.cantidad" class="check"><input v-model="deliveryForm.aceptacion_parcial" type="checkbox" required /> Se informó al cliente y aceptó la entrega parcial</label><p class="small">Los vacíos no retirados quedarán pendientes con fecha. Una parcial conserva el pago y lleva solo el faltante al siguiente turno.</p></template><button class="btn btn-primary" :disabled="busy">{{ online?'Guardar resultado':'Guardar para sincronizar' }}</button></form></div>
  </div>
</template>

